function conversationDoc(test, turn, index) {
  const last = index === test.turns.length - 1;
  const doc = {
    _id: ObjectId(turn.convObjectId),
    conversation: ["## Orchestrator Response\n\n" + turn.response],
    conversationId: test.conversationId,
    finalSentPrompt: turn.user,
    prompt: turn.user,
    response: turn.response,
    timestamp: turn.end,
    toolsMetadata: {},
    validation: true,
  };
  if (last) {
    doc.validationMessage = test.validation;
    doc.remediationMessage = test.remediation;
  } else {
    doc.validationMessage = "null";
    doc.remediationMessage = "null";
  }
  return doc;
}

function buildResult(test) {
  return {
    _id: ObjectId(test.resultObjectId),
    _t: "com.akto.dto.testing.TestingRunResult",
    apiInfoKey: API_INFO_KEY,
    confidencePercentage: 100,
    endTimestamp: test.endTimestamp,
    rerun: false,
    singleTypeInfos: [],
    startTimestamp: test.startTimestamp,
    testResults: test.turns.map(function (turn) {
      return {
        _t: "com.akto.dto.testing.TestResult",
        confidence: test.severity,
        conversationId: test.conversationId,
        errors: [],
        message: turn.message,
        percentageMatch: 100,
        requiresConfig: false,
        resultTypeAgentic: true,
        vulnerable: turn.vulnerable,
      };
    }),
    testRunId: RUN_ID,
    testRunResultSummaryId: SUMMARY_ID,
    testSubType: test.testSubType,
    testSuperType: test.testSuperType,
    vulnerable: true,
  };
}

